import java.util.Scanner;

class Cat {
    static int total = 0;
    String name;

    Cat(String name) {
        this.name = name;
    }

    void eat(int fish) {
        total = total + fish;
        System.out.println(name + "：这一顿 " + fish + " 条");
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Cat a = new Cat("{cat}");
        Cat b = new Cat("{cat2}");
        for (int i = 0; i < n; i++) {
            int fish = sc.nextInt();
            a.eat(fish);
            b.eat(fish);
        }
        System.out.println("一共有 " + Cat.total + " 条");
    }
}
